from openpyxl import load_workbook
from docx import Document
from pathlib import Path
base=Path('/home/oai/share')
for f in ['Flat-Rate-Labour-FY26.xlsx','Labour-Rates-By-Region-FY26.xlsx','Parts-Price-List-FY26.xlsx']:
    print('\n###',f)
    wb=load_workbook(base/f,data_only=True)
    for ws in wb.worksheets:
        print('SHEET',ws.title)
        for row in ws.iter_rows(values_only=True): print(row)
for f in ['SPA-Fabrikam.docx','SPA-Northwind.docx','POL-WAR-4.2.docx','ADD-IN-2.1.docx']:
    print('\n###',f)
    d=Document(base/f)
    for p in d.paragraphs:
        if p.text.strip(): print(p.text)
    for t in d.tables:
        for r in t.rows: print(' | '.join(c.text for c in r.cells))
PY

